SDB_API void sdb_ns_lock(Sdb *s, int lock, int depth) {
        SdbListIter *it;
        SdbNs *ns;
        s->ns_lock = lock;
        if (depth) { // handles -1 as infinite
                ls_foreach (s->ns, it, ns) {
                        sdb_ns_lock (ns->sdb, lock, depth-1);
                }
        }
}

static int in_list(SdbList *list, void *item) {
        SdbNs *ns;
        SdbListIter *it;
        if (list && item)
        ls_foreach (list, it, ns) {
                if (item == ns) {
                        return 1;
                }
        }
        return 0;
}

static void ns_free(Sdb *s, SdbList *list) {
        SdbListIter next;
        SdbListIter *it;
        int deleted;
        SdbNs *ns;
        if (!list || !s) {
                return;
        }
        // TODO: Implement and use ls_foreach_safe
        if (in_list (list, s)) {
                return;
        }
        ls_append (list, s);
        ls_foreach (s->ns, it, ns) {
                deleted = 0;
                next.n = it->n;
                if (!in_list (list, ns)) {
                        ls_delete (s->ns, it); // free (it)
                        free (ns->name);
                        ns->name = NULL;
                        deleted = 1;
                        if (ns->sdb) {
