SDB_API bool sdb_ns_unset (Sdb *s, const char *name, Sdb *r) {
        SdbNs *ns;
        SdbListIter *it;
        if (s && (name || r)) {
                ls_foreach (s->ns, it, ns) {
                        if (name && (!strcmp (name, ns->name))) {
                                ls_delete (s->ns, it);
                                return true;
                        }
                        if (r && ns->sdb == r) {
                                ls_delete (s->ns, it);
                                return true;
                        }
                }
        }
        return false;
}

SDB_API int sdb_ns_set (Sdb *s, const char *name, Sdb *r) {
        SdbNs *ns;
        SdbListIter *it;
        ut32 hash = sdb_hash (name);
        if (!s || !r || !name) {
                return 0;
        }
        ls_foreach (s->ns, it, ns) {
                if (ns->hash == hash) {
                        if (ns->sdb == r) {
                                return 0;
                        }
                        sdb_free (ns->sdb);
                        r->refs++; // sdb_ref / sdb_unref //
                        ns->sdb = r;
                        return 1;
                }
        }
        if (s->ns_lock) {
                return 0;
        }
        ns = R_NEW (SdbNs);
        ns->name = strdup (name);
        ns->hash = hash;
        ns->sdb = r;
        r->refs++;
        ls_append (s->ns, ns);
        return 1;
}

SDB_API Sdb *sdb_ns(Sdb *s, const char *name, int create) {
        SdbListIter *it;
        SdbNs *ns;
        ut32 hash;
        if (!s || !name || !*name) {
                return NULL;
        }
        hash = sdb_hash (name);
        ls_foreach (s->ns, it, ns) {
                if (ns->hash == hash) {
                        return ns->sdb;
                }
        }
        if (!create) {
                return NULL;
        }
        if (s->ns_lock) {
                return NULL;
        }
        ns = sdb_ns_new (s, name, hash);
        if (!ns) {
                return NULL;
        }
        ls_append (s->ns, ns);
        return ns->sdb;
}

SDB_API Sdb *sdb_ns_path(Sdb *s, const char *path, int create) {
        char *ptr, *str;
        char *slash;

        if (!s || !path || !*path)
                return s;
        ptr = str = strdup (path);
        do {
                slash = strchr (ptr, '/');
                if (slash)
                        *slash = 0;
                s = sdb_ns (s, ptr, create);
                if (!s) break;
                if (slash)
                        ptr = slash+1;
        } while (slash);
        free (str);
        return s;
}

static void ns_sync (Sdb *s, SdbList *list) {
        SdbNs *ns;
        SdbListIter *it;
        ls_foreach (s->ns, it, ns) {
                if (in_list (list, ns)) {
                        continue;
                }
                ls_append (list, ns);
                ns_sync (ns->sdb, list);
                sdb_sync (ns->sdb);
        }
        sdb_sync (s);
}

SDB_API void sdb_ns_sync (Sdb *s) {
        SdbList *list = ls_new ();
        ns_sync (s, list);
        list->free = NULL;
        ls_free (list);
}

